import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

import com.vaadin.flow.server.VaadinSession;

/**
 * The messages that have been sent, newest first.
 * <p>
 * The store lives in the Vaadin session, so the list is a list of what has been
 * sent rather than of what one visit to the contact view sent: navigating away
 * from the view and back again still shows it.
 */
public class MessageStore implements Serializable {

    private final List<Message> messages = new ArrayList<>();

    /**
     * The store of the current session, created on first use.
     */
    public static MessageStore current() {
        VaadinSession session = VaadinSession.getCurrent();
        if (session == null) {
            // No session to hang on to (a plain unit test, say); a throw-away
            // store keeps the view usable instead of failing.
            return new MessageStore();
        }
        MessageStore store = session.getAttribute(MessageStore.class);
        if (store == null) {
            store = new MessageStore();
            session.setAttribute(MessageStore.class, store);
        }
        return store;
    }

    public void add(Message message) {
        messages.add(0, message);
    }

    /**
     * Everything sent so far, newest first.
     */
    public List<Message> newestFirst() {
        return List.copyOf(messages);
    }
}
