    private ContactView contact() {
        return navigate(ContactView.class);
    }

    private void fill(ContactView view, String name, String email,
            String phone, String message) {
        test(view.name).setValue(name);
        test(view.email).setValue(email);
        test(view.phone).setValue(phone);
        test(view.message).setValue(message);
    }

    // -- The views ------------------------------------------------------

    @Test
    void contactRoute_showsHeadingLinkFormAndGrid() {
        navigate("contact", ContactView.class);

        Assertions.assertEquals("Contact",
                find(H1.class).single().getText());
        Assertions.assertTrue(
                find(RouterLink.class).withText("About").exists());
        Assertions.assertTrue(
                find(TextField.class).withLabel("Name").exists());
        Assertions.assertTrue(
                find(EmailField.class).withLabel("Email").exists());
        Assertions.assertTrue(
                find(TextField.class).withLabel("Phone").exists());
        Assertions.assertTrue(
                find(TextArea.class).withLabel("Message").exists());
        Assertions.assertTrue(find(Button.class).withText("Send").exists());
        Assertions.assertTrue(find(Grid.class).exists());
    }

    @Test
