        navigate("about", AboutView.class);

        Assertions.assertEquals("About", find(H1.class).single().getText());
    }

    @Test
    void aboutLink_navigatesToAboutView() {
        contact();

        test(find(RouterLink.class).withText("About").single()).click();

        Assertions.assertInstanceOf(AboutView.class, getCurrentView());
    }

    @Test
    void untouchedForm_isEmptyAndSendIsEnabled() {
        ContactView view = contact();

        Assertions.assertEquals("", view.name.getValue());
        Assertions.assertEquals("", view.email.getValue());
        Assertions.assertEquals("", view.phone.getValue());
        Assertions.assertEquals("", view.message.getValue());
        Assertions.assertTrue(test(view.send).isUsable(),
                "Send must be enabled on an untouched form");
    }

    // -- Validating -----------------------------------------------------

