+        fill("Ada", "not-an-address", "", "Hello");
+
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+    }
+
+    @Test
+    void tooLongMessage_send_showsTheLengthErrorMessage() {
+        fill("Ada", "ada@example.com", "", "x".repeat(501));
+
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+    }
+
+    @Test
+    void invalidForm_send_keepsWhatWasTypedAndNotifiesNothing() {
+        fill("", "ada@example.com", "", "Hello");
+
+        send().click();
+
+        email().assertValue("ada@example.com");
+        message().assertValue("Hello");
+        send().assertEnabled();
+        PlaywrightAssertions
+                .assertThat(page.locator("vaadin-notification-card"))
+                .hasCount(0);
+    }
+
+    @Test
+    void validForm_send_notifiesListsClearsAndDisablesSend() {
+        fill("Ada", "ada@example.com", "", "Hello there");
+
+        send().click();
+
+        new NotificationElement(page).assertOpen();
+        PlaywrightAssertions
+                .assertThat(page.locator("vaadin-notification-card"))
+                .containsText("Message sent");
+
+        GridElement grid = GridElement.get(page);
+        PlaywrightAssertions.assertThat(grid.getLocator()).containsText("Ada");
+        PlaywrightAssertions.assertThat(grid.getLocator())
+                .containsText("Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        // ... and enabled again as soon as the user edits anything.
+        name().setValue("B");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enterKey_sendsTheMessage() {
+        fill("Ada", "ada@example.com", "", "Sent with Enter");
+
+        message().getInputLocator().press("Enter");
+
+        PlaywrightAssertions
+                .assertThat(page.locator("vaadin-notification-card"))
+                .containsText("Message sent");
+        PlaywrightAssertions.assertThat(GridElement.get(page).getLocator())
+                .containsText("Sent with Enter");
+    }
+
+    @Test
+    void sentMessages_surviveLeavingAndComingBack() {
+        fill("Ada", "ada@example.com", "", "Still here?");
+        send().click();
+        new NotificationElement(page).assertOpen();
+
+        page.getByText("About").click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        page.getByText("Contact").click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+
+        PlaywrightAssertions.assertThat(GridElement.get(page).getLocator())
+                .containsText("Still here?");
+    }
+
+    @Test
+    void emptyForm_leaving_isNotInterrupted() {
+        page.getByText("About").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        // Only the dev-mode overlays are around; nothing asked to keep editing.
+        PlaywrightAssertions
+                .assertThat(page.getByText("Keep editing")).hasCount(0);
+    }
+
+    @Test
+    void filledForm_keepEditing_staysWithTheFormUntouched() {
+        name().setValue("Ada");
+        message().setValue("Half written");
+
+        page.getByText("About").click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        dialog.assertClosed();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("Ada");
+        message().assertValue("Half written");
+    }
+
+    @Test
+    void filledForm_discard_goesAhead() {
+        name().setValue("Ada");
+
+        page.getByText("About").click();
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+    }
+}
