+
+    @Test
+    void blankMessage_send_marksMessage() {
+        ContactView view = contact();
+        fill(view, "Ada", "ada@example.com", "", "   ");
+
+        test(view.send).click();
+
+        Assertions.assertTrue(view.message.isInvalid());
+        Assertions.assertEquals("Message is required",
+                view.message.getErrorMessage());
+    }
+
+    @Test
+    void tooLongMessage_send_marksMessage() {
+        ContactView view = contact();
+        fill(view, "Ada", "ada@example.com", "", "x".repeat(501));
+
+        test(view.send).click();
+
+        Assertions.assertTrue(view.message.isInvalid());
+        Assertions.assertEquals("Message must be at most 500 characters",
+                view.message.getErrorMessage());
+        Assertions.assertEquals(0, test(view.sent).size());
+    }
+
+    @Test
+    void exactly500Characters_send_isAccepted() {
