+    }
+
+    @Test
+    void invalidForm_send_sendsNothingAndKeepsInput() {
+        ContactView view = contact();
+        fill(view, "", "ada@example.com", "", "Hello");
+
+        test(view.send).click();
+
+        Assertions.assertFalse(find(Notification.class).exists(),
+                "No notification when validation fails");
+        Assertions.assertEquals(0, test(view.sent).size());
+        Assertions.assertEquals("ada@example.com", view.email.getValue());
+        Assertions.assertEquals("Hello", view.message.getValue());
+        Assertions.assertTrue(test(view.send).isUsable());
+    }
+
+    @Test
+    void phoneOnly_send_isAccepted() {
+        ContactView view = contact();
+        fill(view, "Ada", "", "+358 40 123 4567", "Call me");
+
+        test(view.send).click();
+
+        Assertions.assertFalse(view.email.isInvalid());
+        Assertions.assertEquals(1, test(view.sent).size());
+    }
+
+    @Test
+    void emailOnly_send_isAccepted() {
+        ContactView view = contact();
+        fill(view, "Ada", "ada@example.com", "", "Write to me");
+
+        test(view.send).click();
+
+        Assertions.assertFalse(view.email.isInvalid());
+        Assertions.assertEquals(1, test(view.sent).size());
+    }
+
+    // -- Sending --------------------------------------------------------
+
+    @Test
+    void validForm_send_notifiesListsClearsAndDisablesSend() {
+        ContactView view = contact();
+        fill(view, "Ada", "ada@example.com", "", "Hello there");
+
+        test(view.send).click();
+
+        Notification notification = find(Notification.class).single();
+        Assertions.assertTrue(
+                test(notification).getText().contains("Message sent"),
